def specialFilter(nums):
    def isOdd(d):
        return d % 2 == 1

    def firstDigit(x):
        while x >= 10:
            x //= 10
        return x

    def lastDigit(x):
        return abs(x) % 10

    def isFirstAndLastDigitOdd(x):
        return isOdd(firstDigit(x)) and isOdd(lastDigit(x))

    count = 0
    for num in nums:
        if num > 10 and isFirstAndLastDigitOdd(num):
            count += 1

    return count

